package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.jsoup.helper.HttpConnection;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.FormElement;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class FormElement_formData_TriageGen2Test {

    private FormElement formElement;

    @Before
    public void setUp() {
        Attributes attributes = new Attributes();
        formElement = new FormElement(new org.jsoup.nodes.Tag("form"), "", attributes);
    }

    @Test
    public void testEmptyForm() {
        List<Connection.KeyVal> formData = formElement.formData();
        assertEquals(0, formData.size());
    }

    @Test
    public void testDisabledInput() {
        Element input = mock(Element.class);
        when(input.tag().isFormSubmittable()).thenReturn(true);
        when(input.hasAttr("disabled")).thenReturn(true);
        when(input.attr("name")).thenReturn("testName");
        formElement.addElement(input);

        List<Connection.KeyVal> formData = formElement.formData();
        assertEquals(0, formData.size());
    }

    @Test
    public void testInputWithoutName() {
        Element input = mock(Element.class);
        when(input.tag().isFormSubmittable()).thenReturn(true);
        when(input.hasAttr("disabled")).thenReturn(false);
        when(input.attr("name")).thenReturn("");
        formElement.addElement(input);

        List<Connection.KeyVal> formData = formElement.formData();
        assertEquals(0, formData.size());
    }

    @Test
    public void testTextInput() {
        Element input = mock(Element.class);
        when(input.tag().isFormSubmittable()).thenReturn(true);
        when(input.hasAttr("disabled")).thenReturn(false);
        when(input.attr("name")).thenReturn("textInput");
        when(input.val()).thenReturn("testValue");
        formElement.addElement(input);

        List<Connection.KeyVal> formData = formElement.formData();
        assertEquals(1, formData.size());
        assertEquals("testValue", formData.get(0).value());
    }

    @Test
    public void testCheckedCheckbox() {
        Element checkbox = mock(Element.class);
        when(checkbox.tag().isFormSubmittable()).thenReturn(true);
        when(checkbox.hasAttr("disabled")).thenReturn(false);
        when(checkbox.attr("name")).thenReturn("checkbox");
        when(checkbox.attr("type")).thenReturn("checkbox");
        when(checkbox.hasAttr("checked")).thenReturn(true);
        when(checkbox.val()).thenReturn("checkedValue");
        formElement.addElement(checkbox);

        List<Connection.KeyVal> formData = formElement.formData();
        assertEquals(1, formData.size());
        assertEquals("checkedValue", formData.get(0).value());
    }

    @Test
    public void testUncheckedCheckbox() {
        Element checkbox = mock(Element.class);
        when(checkbox.tag().isFormSubmittable()).thenReturn(true);
        when(checkbox.hasAttr("disabled")).thenReturn(false);
        when(checkbox.attr("name")).thenReturn("checkbox");
        when(checkbox.attr("type")).thenReturn("checkbox");
        when(checkbox.hasAttr("checked")).thenReturn(false);
        formElement.addElement(checkbox);

        List<Connection.KeyVal> formData = formElement.formData();
        assertEquals(0, formData.size());
    }

    @Test
    public void testSelectedOption() {
        Element select = mock(Element.class);
        when(select.tag().isFormSubmittable()).thenReturn(true);
        when(select.hasAttr("disabled")).thenReturn(false);
        when(select.attr("name")).thenReturn("select");
        when(select.normalName()).thenReturn("select");

        Element option = mock(Element.class);
        when(option.val()).thenReturn("selectedValue");
        Elements options = new Elements();
        options.add(option);

        when(select.select("option[selected]")).thenReturn(options);
        formElement.addElement(select);

        List<Connection.KeyVal> formData = formElement.formData();
        assertEquals(1, formData.size());
        assertEquals("selectedValue", formData.get(0).value());
    }

    @Test
    public void testSelectWithNoSelectedOption() {
        Element select = mock(Element.class);
        when(select.tag().isFormSubmittable()).thenReturn(true);
        when(select.hasAttr("disabled")).thenReturn(false);
        when(select.attr("name")).thenReturn("select");
        when(select.normalName()).thenReturn("select");

        Element option = mock(Element.class);
        when(option.val()).thenReturn("defaultValue");
        Elements options = new Elements();
        when(select.select("option")).thenReturn(options);
        formElement.addElement(select);

        List<Connection.KeyVal> formData = formElement.formData();
        assertEquals(1, formData.size());
        assertEquals("defaultValue", formData.get(0).value());
    }

    @Test
    public void testRadioInputChecked() {
        Element radio = mock(Element.class);
        when(radio.tag().isFormSubmittable()).thenReturn(true);
        when(radio.hasAttr("disabled")).thenReturn(false);
        when(radio.attr("name")).thenReturn("radio");
        when(radio.attr("type")).thenReturn("radio");
        when(radio.hasAttr("checked")).thenReturn(true);
        when(radio.val()).thenReturn("radioValue");
        formElement.addElement(radio);

        List<Connection.KeyVal> formData = formElement.formData();
        assertEquals(1, formData.size());
        assertEquals("radioValue", formData.get(0).value());
    }

    @Test
    public void testRadioInputUnchecked() {
        Element radio = mock(Element.class);
        when(radio.tag().isFormSubmittable()).thenReturn(true);
        when(radio.hasAttr("disabled")).thenReturn(false);
        when(radio.attr("name")).thenReturn("radio");
        when(radio.attr("type")).thenReturn("radio");
        when(radio.hasAttr("checked")).thenReturn(false);
        formElement.addElement(radio);

        List<Connection.KeyVal> formData = formElement.formData();
        assertEquals(0, formData.size());
    }
}
